        public static string Get(string cmd)
        {
            string t;
            return T.TryGetValue(cmd, out t) ? t : "";
        }

        /// <summary>Подсказка для кнопки: название, описание и команда для командной строки.</summary>
        public static string For(string title, string cmd)
        {
            string d = Get(cmd);
            return title + (d != "" ? "\n" + d : "") + "\nКоманда: " + cmd;
        }
